css:
html{-webkit-text-size-adjust:100%}
body{margin:0;background:#F9F4EC}
.bt-pg{--navy:#004877;--ink:#1d1e1f;--cream:#F9F4EC;--sand:#F3E9D9;--sky:#3C96E7;--pale:#AED3F5;--line:rgba(0,72,119,.16);--line2:rgba(0,72,119,.08);--mut:rgba(0,72,119,.66);--body:rgba(29,30,31,.78);--serif:"Bodoni Moda","Bodoni MT",Didot,Georgia,serif;--sans:"Jost","Century Gothic",Futura,"Helvetica Neue",Arial,sans-serif;--gut:clamp(20px,4vw,56px);--ease:cubic-bezier(.2,.7,.2,1);display:block;font-family:var(--sans);font-size:16.5px;line-height:1.65;color:var(--ink);background:var(--cream);-webkit-font-smoothing:antialiased;font-optical-sizing:none;font-variation-settings:"opsz" 30}
.bt-pg *,.bt-pg *::before,.bt-pg *::after{box-sizing:border-box}
.bt-pg a{color:inherit;text-decoration:none}
.bt-pg p{margin:0}
.bt-pg ul,.bt-pg ol{list-style:none;margin:0;padding:0}
.bt-pg img{display:block;max-width:100%}
.bt-pg button,.bt-pg input,.bt-pg select,.bt-pg textarea{font-family:inherit;color:inherit}
.bt-pg svg{width:18px;height:18px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.bt-pg [hidden]{display:none!important}
.bt-pg a:focus-visible,.bt-pg button:focus-visible,.bt-pg input:focus-visible,.bt-pg select:focus-visible,.bt-pg textarea:focus-visible,.bt-pg label:focus-visible{outline:2px solid var(--sky);outline-offset:2px}
.bt-pg .bt-js-only{display:none}
html.bt-js .bt-pg .bt-js-only{display:block}
html.bt-js .bt-pg .bt-nojs{display:none}
.bt-pg .bt-wrap{max-width:1472px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.bt-pg h1,.bt-pg h2,.bt-pg h3{font-family:var(--serif);font-weight:400;letter-spacing:-.012em;margin:0;text-wrap:balance}
.bt-pg h1{font-size:clamp(40px,5.4vw,76px);line-height:1.02}
.bt-pg h2{font-size:clamp(30px,3.2vw,46px);line-height:1.08}
.bt-pg h1 em,.bt-pg h2 em{font-style:italic;color:var(--navy)}
.bt-pg .bt-kicker{display:flex;align-items:center;gap:14px;font-size:12.5px;line-height:1;font-weight:500;letter-spacing:.24em;text-transform:uppercase;color:var(--navy);margin-bottom:22px}
.bt-pg .bt-kicker::before{content:"";width:40px;height:1px;background:currentColor;flex:none}
.bt-pg .bt-lead{color:var(--body);max-width:56ch;margin-top:20px}
.bt-pg .bt-crumbs{display:flex;flex-wrap:wrap;gap:10px;font-size:12px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;color:var(--mut);margin-bottom:clamp(24px,3vw,40px)}
.bt-pg .bt-crumbs a:hover{color:var(--navy)}
.bt-pg .bt-btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:54px;padding:0 28px;font-family:var(--sans);font-size:12.5px;line-height:1.2;font-weight:500;letter-spacing:.2em;text-transform:uppercase;text-align:center;border:1px solid var(--navy);border-radius:2px;background:var(--navy);color:#fff;cursor:pointer;transition:background .5s var(--ease),color .5s var(--ease),border-color .5s var(--ease),gap .5s var(--ease)}
.bt-pg .bt-btn:hover{background:transparent;color:var(--navy);gap:16px}
.bt-pg .bt-btn svg{width:14px;height:14px}
.bt-pg .bt-btn-line{background:transparent;color:var(--navy)}
.bt-pg .bt-btn-line:hover{background:var(--navy);color:#fff}
.bt-pg .bt-btn-cream{background:var(--cream);border-color:var(--cream);color:var(--navy)}
.bt-pg .bt-btn-cream:hover{background:transparent;color:var(--cream)}
.bt-pg .bt-btn-block{display:flex;width:100%}
.bt-pg .bt-link{display:inline-flex;align-items:center;gap:10px;font-size:12px;line-height:1.2;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--navy);border:0;border-bottom:1px solid currentColor;background:none;padding:0 0 6px;cursor:pointer;transition:gap .5s var(--ease)}
.bt-pg .bt-link:hover{gap:16px}
.bt-pg .bt-link svg{width:14px;height:14px}
.bt-pg .bt-top{padding:clamp(28px,3.4vw,52px) 0 clamp(30px,3.6vw,56px);border-bottom:1px solid var(--line)}
.bt-pg .bt-top-in{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:clamp(24px,4vw,72px);align-items:end}
/* three step flow: tiles flip as each step is reached */
.bt-pg .bt-flow{display:flex;align-items:flex-start;gap:clamp(18px,2.4vw,40px);perspective:600px}
.bt-pg .bt-flow li{position:relative;display:flex;flex-direction:column;gap:12px;min-width:0;font-size:11.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--mut)}
.bt-pg .bt-flow li+li::before{content:"";position:absolute;right:calc(100% + 6px);top:17px;width:clamp(6px,1.4vw,28px);height:1px;background:var(--line)}
.bt-pg .bt-flow i{display:flex;align-items:center;justify-content:center;width:36px;height:36px;border:1px solid var(--line);font-family:var(--serif);font-style:normal;font-size:17px;letter-spacing:0;color:var(--navy);background:var(--cream)}
.bt-pg .bt-flow .bt-on{color:var(--navy)}
.bt-pg .bt-flow .bt-on i,.bt-pg .bt-flow .bt-done i{background:var(--navy);border-color:var(--navy);color:#fff}
.bt-pg .bt-flow .bt-on i{box-shadow:0 14px 22px -12px rgba(0,72,119,.8);animation:btFlowFlip 1.1s var(--ease) both}
.bt-pg .bt-flow .bt-done{color:var(--navy)}
@keyframes btFlowFlip{from{transform:rotateY(-180deg);background:var(--cream);color:transparent}to{transform:none}}
.bt-pg .bt-sec{padding:clamp(36px,4.6vw,72px) 0 clamp(64px,8vw,120px)}
/* shared navy panel with a tiled floor */
.bt-pg .bt-navy{position:relative;isolation:isolate;overflow:hidden;color:#fff;background:linear-gradient(160deg,#004877 0%,#00365b 46%,#001a2e 100%)}
.bt-pg .bt-floor{position:absolute;left:0;right:0;bottom:0;z-index:-1;height:190px;overflow:hidden;perspective:340px;perspective-origin:50% 0;opacity:.5;pointer-events:none;-webkit-mask-image:linear-gradient(180deg,transparent 0,#000 70%);mask-image:linear-gradient(180deg,transparent 0,#000 70%)}
.bt-pg .bt-floor i{position:absolute;left:-120%;right:-120%;top:0;height:900px;transform-origin:50% 0;transform:translateZ(-300px) rotateX(76deg);background-image:linear-gradient(rgba(174,211,245,.42) 1.5px,transparent 1.5px),linear-gradient(90deg,rgba(174,211,245,.42) 1.5px,transparent 1.5px);background-size:74px 74px;animation:btPgFloor 18s linear infinite}
@keyframes btPgFloor{to{background-position:0 148px}}
.bt-pg .bt-ticks li{position:relative;padding-left:22px;font-size:14.5px;line-height:1.5}
.bt-pg .bt-ticks li+li{margin-top:10px}
.bt-pg .bt-ticks li::before{content:"";position:absolute;left:1px;top:7px;width:7px;height:7px;border:1px solid currentColor;transform:rotate(45deg);opacity:.9}
/* product thumb used in cart lines and summaries */
.bt-pg .bt-line-img{position:relative;display:block;overflow:hidden;background:var(--sand);box-shadow:0 0 0 1px var(--line)}
.bt-pg .bt-line-img img{width:100%;height:100%;object-fit:cover}
.bt-pg .bt-line-img:empty::after{content:"";position:absolute;left:50%;top:50%;width:34%;height:34%;margin:-17% 0 0 -17%;border:1px solid var(--mut);transform:rotate(45deg)}
.bt-pg .bt-sum-line{display:grid;grid-template-columns:58px minmax(0,1fr) auto;gap:14px;align-items:start;padding:16px 0;border-bottom:1px solid var(--line)}
.bt-pg .bt-sum-line .bt-line-img{width:58px;height:58px}
.bt-pg .bt-sum-t{font-family:var(--serif);font-size:19px;line-height:1.15}
.bt-pg .bt-sum-m,.bt-pg .bt-sum-q{font-size:13.5px;line-height:1.45;color:var(--body);margin-top:3px}
.bt-pg .bt-sum-e{font-weight:500;font-size:15px;color:var(--navy);white-space:nowrap;padding-top:2px}
@media (max-width:900px){
.bt-pg .bt-top-in{grid-template-columns:minmax(0,1fr)}
}
@media (max-width:760px){
.bt-pg{font-size:16px}
.bt-pg .bt-sec{padding-bottom:calc(88px + env(safe-area-inset-bottom))}
.bt-pg .bt-flow{gap:14px;justify-content:space-between}
.bt-pg .bt-flow li{font-size:10px;letter-spacing:.12em}
.bt-pg .bt-flow li+li::before{display:none}
}
@media (prefers-reduced-motion:reduce){.bt-pg *,.bt-pg *::before,.bt-pg *::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}.bt-pg .bt-floor i{animation:none!important}}
.bt-cartp .bt-cart-grid{display:flex;align-items:flex-start;gap:clamp(28px,4vw,72px)}
.bt-cartp .bt-cart-main{flex:1;min-width:0}
.bt-cartp .bt-cart-aside{flex:0 0 min(420px,36%);position:sticky;top:104px;padding:clamp(26px,2.6vw,38px)}
.bt-cartp .bt-nojs{padding:26px 28px;border:1px solid var(--line);background:var(--sand)}
.bt-cartp .bt-nojs b{display:block;font-family:var(--serif);font-weight:400;font-size:26px;line-height:1.15;margin-bottom:8px}
.bt-cartp .bt-nojs .bt-btn{margin-top:18px}
.bt-cartp .bt-flash{display:inline-block;background:var(--navy);color:#fff;font-size:12px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;padding:11px 18px;margin-bottom:18px;animation:btCartFlash .6s var(--ease) both}
@keyframes btCartFlash{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}
.bt-cartp .bt-cart-bar{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-bottom:16px;border-bottom:1px solid var(--navy)}
.bt-cartp .bt-cart-bar p{font-size:11.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--navy)}
.bt-cartp .bt-cart-bar .bt-link{font-size:11px;color:var(--mut)}
.bt-cartp .bt-line{display:grid;grid-template-columns:118px minmax(0,1fr);column-gap:clamp(18px,2vw,30px);padding:28px 0;border-bottom:1px solid var(--line);perspective:700px}
.bt-cartp .bt-line>*{grid-column:2}
.bt-cartp .bt-line>.bt-line-img{grid-column:1;grid-row:1 / span 4;width:118px;height:118px;transition:transform .8s var(--ease),box-shadow .8s var(--ease)}
.bt-cartp .bt-line:hover>.bt-line-img{transform:rotateY(-14deg) rotateX(5deg);box-shadow:0 0 0 1px var(--line),16px 22px 30px -20px rgba(17,18,19,.6)}
.bt-cartp .bt-line-top{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}
.bt-cartp .bt-line-k{font-size:10.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--mut);margin-bottom:6px}
.bt-cartp .bt-line-title{font-family:var(--serif);font-size:clamp(24px,2.2vw,31px);line-height:1.1;transition:color .3s}
.bt-cartp .bt-line-title:hover{color:var(--navy)}
.bt-cartp .bt-line-x{flex-shrink:0;display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;margin:-8px -10px 0 0;border:0;background:transparent;color:var(--mut);cursor:pointer;transition:color .3s,transform .6s var(--ease)}
.bt-cartp .bt-line-x:hover{color:var(--navy);transform:rotate(90deg)}
.bt-cartp .bt-line-x svg{width:16px;height:16px}
.bt-cartp .bt-line-meta{font-size:14.5px;color:var(--body);margin-top:6px}
.bt-cartp .bt-line-qty{display:flex;align-items:center;flex-wrap:wrap;gap:12px 24px;margin-top:18px}
.bt-cartp .bt-field{display:inline-flex;align-items:center;gap:10px;font-size:11px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;color:var(--mut)}
.bt-cartp .bt-field input[type=number]{width:104px;min-width:0;height:46px;border:1px solid var(--line);border-radius:2px;background:#fff;padding:0 12px;font-size:16px;color:var(--ink);letter-spacing:0}
.bt-cartp .bt-check{display:inline-flex;align-items:center;gap:9px;font-size:14px;color:var(--body);cursor:pointer}
.bt-cartp .bt-check input{width:17px;height:17px;accent-color:var(--navy);margin:0}
.bt-cartp .bt-stepper{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:2px;background:#fff}
.bt-cartp .bt-stepper button{width:46px;height:46px;border:0;background:transparent;font-size:18px;color:var(--navy);cursor:pointer;padding:0}
.bt-cartp .bt-stepper output{min-width:40px;text-align:center;font-size:16px}
.bt-cartp .bt-line-calc{margin-top:14px;font-size:14.5px;color:var(--body)}
.bt-cartp .bt-line-calc b{color:var(--navy);font-weight:500}
.bt-cartp .bt-cart-under{display:flex;flex-wrap:wrap;gap:16px 30px;margin-top:26px}
/* empty state */
.bt-cartp .bt-empty{display:grid;grid-template-columns:auto minmax(0,1fr);gap:clamp(26px,4vw,64px);align-items:center;padding:clamp(30px,4vw,60px);border:1px solid var(--line);background:var(--sand)}
.bt-cartp .bt-empty-tile{width:clamp(110px,13vw,170px);aspect-ratio:1;perspective:700px}
.bt-cartp .bt-empty-tile i{display:block;width:100%;height:100%;background:linear-gradient(135deg,#fff 0%,#e9e1d3 46%,#cfc6b6 100%);box-shadow:26px 34px 44px -26px rgba(17,18,19,.55);animation:btEmptySpin 9s ease-in-out infinite alternate}
@keyframes btEmptySpin{from{transform:rotateX(18deg) rotateY(-34deg)}to{transform:rotateX(8deg) rotateY(34deg)}}
.bt-cartp .bt-empty h2{margin-bottom:12px}
.bt-cartp .bt-empty p{color:var(--body);max-width:52ch}
.bt-cartp .bt-empty-cta{display:flex;flex-wrap:wrap;gap:12px;margin-top:26px}
/* summary */
.bt-cartp .bt-as-k{font-size:11px;font-weight:500;letter-spacing:.24em;text-transform:uppercase;color:var(--pale)}
.bt-cartp .bt-as-h{font-family:var(--serif);font-size:32px;line-height:1.05;margin:10px 0 22px}
.bt-cartp .bt-as-row{display:flex;align-items:baseline;justify-content:space-between;gap:16px;padding:14px 0;border-top:1px solid rgba(174,211,245,.24);font-size:11.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--pale)}
.bt-cartp .bt-as-row b{font-family:var(--serif);font-weight:400;font-size:17px;letter-spacing:0;text-transform:none;color:#fff}
.bt-cartp .bt-as-row.bt-as-total b{font-size:38px;line-height:1}
.bt-cartp .bt-as-fine{font-size:13.5px;line-height:1.5;color:rgba(255,255,255,.74);margin:2px 0 22px}
.bt-cartp .bt-cart-aside .bt-ticks{margin-top:24px;color:rgba(255,255,255,.88)}
.bt-cartp .bt-as-call{display:block;margin-top:22px;padding-top:18px;border-top:1px solid rgba(174,211,245,.24);font-size:14.5px;color:rgba(255,255,255,.8)}
.bt-cartp .bt-as-call a{color:#fff;border-bottom:1px solid rgba(255,255,255,.6)}
/* add a BT Special */
.bt-cartp .bt-more{padding:clamp(56px,7vw,104px) 0;background:var(--sand)}
.bt-cartp .bt-more-head{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:clamp(28px,3.4vw,48px)}
.bt-cartp .bt-more-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(14px,1.6vw,26px);perspective:1800px}
.bt-cartp .bt-mc{display:flex;flex-direction:column;min-width:0;background:var(--cream);box-shadow:0 0 0 1px var(--line);transition:transform .9s var(--ease),box-shadow .9s var(--ease)}
.bt-cartp .bt-mc:hover{transform:translateY(-8px) rotateX(3deg);box-shadow:0 0 0 1px var(--line),0 40px 50px -36px rgba(17,18,19,.6)}
.bt-cartp .bt-mc-img{display:block;aspect-ratio:4/3;overflow:hidden;background:var(--sand)}
.bt-cartp .bt-mc-img img{width:100%;height:100%;object-fit:cover;transition:transform 1.6s var(--ease)}
.bt-cartp .bt-mc:hover .bt-mc-img img{transform:scale(1.07)}
.bt-cartp .bt-mc-b{display:flex;flex-direction:column;flex:1;padding:20px 20px 22px}
.bt-cartp .bt-mc-k{font-size:10.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--mut)}
.bt-cartp .bt-mc h3{font-size:25px;line-height:1.1;margin:6px 0 4px}
.bt-cartp .bt-mc-p{font-size:14px;color:var(--body);margin-bottom:16px}
.bt-cartp .bt-mc-p b{font-family:var(--serif);font-weight:400;font-size:21px;color:var(--navy)}
.bt-cartp .bt-mc .bt-btn{margin-top:auto;min-height:48px;padding:0 14px;font-size:11.5px;letter-spacing:.16em}
@media (max-width:1023px){
.bt-cartp .bt-cart-grid{flex-direction:column}
.bt-cartp .bt-cart-aside{position:static;flex:none;width:100%}
.bt-cartp .bt-more-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (max-width:600px){
.bt-cartp .bt-line{grid-template-columns:78px minmax(0,1fr)}
.bt-cartp .bt-line>.bt-line-img{width:78px;height:78px;grid-row:1 / span 2}
.bt-cartp .bt-line-qty,.bt-cartp .bt-line-calc{grid-column:1 / -1}
.bt-cartp .bt-empty{grid-template-columns:minmax(0,1fr)}
.bt-cartp .bt-empty-tile{width:104px}
.bt-cartp .bt-empty-cta .bt-btn{flex:1 1 100%}
.bt-cartp .bt-mc-b{padding:14px 14px 16px}
.bt-cartp .bt-mc h3{font-size:20px}
}
